-- Run after customer_chat_regression.sql, using rollback-only fixtures.
reset role;
create temporary table photo_test(path text,request_id uuid) on commit drop;
insert into photo_test values(pg_temp.fixture_id('customer_auth')::text||'/'||pg_temp.chat_id()::text||'/dddddddd-0000-4000-8000-000000000099.jpg','dddddddd-0000-4000-8000-000000000099');
grant select on photo_test to authenticated;
set local role authenticated;
select pg_temp.login_as('customer_auth','aal1');
select pg_temp.test_assert('photo upload own conversation allowed',private.chat_photo_access((select path from photo_test),true));
select pg_temp.test_assert('photo malformed path rejected',not private.chat_photo_access('bad/path/file.jpg',true));
select pg_temp.test_error('photo send requires uploaded object',$$select public.chat_send_photo(pg_temp.chat_id(),(select path from photo_test),(select request_id from photo_test))$$,'P0001');
insert into storage.objects(bucket_id,name,owner_id,metadata) select 'chat-photos',path,auth.uid()::text,'{"size":128,"mimetype":"image/jpeg"}'::jsonb from photo_test;
select pg_temp.login_as('provider_auth','aal1');
select pg_temp.test_assert('recipient cannot read unsent photo',not exists(select 1 from storage.objects where bucket_id='chat-photos' and name=(select path from photo_test)));
select pg_temp.login_as('customer_auth','aal1');
select public.chat_send_photo(pg_temp.chat_id(),(select path from photo_test),(select request_id from photo_test));
select public.chat_send_photo(pg_temp.chat_id(),(select path from photo_test),(select request_id from photo_test));
select pg_temp.test_assert('photo retry inserts once',(select count(*)=1 from public.chat_messages where request_id=(select request_id from photo_test)));
select pg_temp.test_assert('photo history includes private path',public.chat_history(pg_temp.chat_id())->'messages'->0->>'attachment_path'=(select path from photo_test));
select pg_temp.test_assert('photo cannot be overwritten',not private.chat_photo_access((select path from photo_test),true));
select pg_temp.login_as('provider_auth','aal1');
select pg_temp.test_assert('recipient can read sent photo',exists(select 1 from storage.objects where bucket_id='chat-photos' and name=(select path from photo_test)));
select public.chat_manage(pg_temp.chat_id(),'delete');
select pg_temp.test_assert('cleared recipient cannot read old photo',not exists(select 1 from storage.objects where bucket_id='chat-photos' and name=(select path from photo_test)));
select pg_temp.login_as('customer_auth','aal1');
select pg_temp.test_assert('recipient deletion preserves sender photo',exists(select 1 from storage.objects where bucket_id='chat-photos' and name=(select path from photo_test)));
select set_config('request.jwt.claim.sub','eeeeeeee-0000-4000-8000-000000000021',true);
select set_config('request.jwt.claims','{"sub":"eeeeeeee-0000-4000-8000-000000000021","role":"authenticated","aal":"aal1"}',true);
select pg_temp.test_assert('other customer cannot read photos',not exists(select 1 from storage.objects where bucket_id='chat-photos' and name=(select path from photo_test)));
select pg_temp.test_assert('other customer cannot upload to conversation',not private.chat_photo_access(replace((select path from photo_test),pg_temp.fixture_id('customer_auth')::text,auth.uid()::text),true));
select pg_temp.test_error('other customer cannot send photo',$$select public.chat_send_photo(pg_temp.chat_id(),replace((select path from photo_test),pg_temp.fixture_id('customer_auth')::text,auth.uid()::text),(select request_id from photo_test))$$,'42501');
reset role;
select pg_temp.test_assert('anonymous cannot send photos',not has_function_privilege('anon','public.chat_send_photo(uuid,text,uuid)','execute'));
select pg_temp.test_assert('photo bucket is private and bounded',(select not public and file_size_limit=5242880 from storage.buckets where id='chat-photos'));
select jsonb_build_object('passed',count(*)) from pg_temp.admin_regression_results;
